package usage

import (
	"regexp"
	"strings"

	"github.com/gratycodes/kube-rightsize-diff/internal/manifest"
)

// Pod name suffixes generated by the built-in controllers. Without
// kube-state-metrics we cannot read ownerReferences, so pods are matched
// to workloads by name, longest workload name first.
var podSuffix = map[string]*regexp.Regexp{
	"Deployment":  regexp.MustCompile(`^-[a-z0-9]{1,10}-[a-z0-9]{5}$`), // <rs-hash>-<pod>
	"ReplicaSet":  regexp.MustCompile(`^-[a-z0-9]{5}$`),
	"StatefulSet": regexp.MustCompile(`^-[0-9]+$`),
	"DaemonSet":   regexp.MustCompile(`^-[a-z0-9]{5}$`),
	"Job":         regexp.MustCompile(`^-[a-z0-9]{5}$`),
	"CronJob":     regexp.MustCompile(`^-[0-9]+-[a-z0-9]{5}$`),
	"Pod":         regexp.MustCompile(`^$`),
}

type workloadRef struct {
	namespace, kind, name string
}

// ownerIndex resolves a pod name to the workload that created it.
type ownerIndex struct {
	byNamespace map[string][]workloadRef
}

func newOwnerIndex(cs []manifest.Container) ownerIndex {
	idx := ownerIndex{byNamespace: map[string][]workloadRef{}}
	seen := map[workloadRef]bool{}
	for _, c := range cs {
		w := workloadRef{c.Namespace, c.Kind, c.Workload}
		if seen[w] {
			continue
		}
		seen[w] = true
		idx.byNamespace[c.Namespace] = append(idx.byNamespace[c.Namespace], w)
	}
	return idx
}

func (o ownerIndex) owner(namespace, pod string) (workloadRef, bool) {
	var best workloadRef
	found := false
	for _, w := range o.byNamespace[namespace] {
		if !strings.HasPrefix(pod, w.name) {
			continue
		}
		re, ok := podSuffix[w.kind]
		if !ok || !re.MatchString(pod[len(w.name):]) {
			continue
		}
		if !found || len(w.name) > len(best.name) {
			best, found = w, true
		}
	}
	return best, found
}
